import { operation } from "@tinker/core";
import { database } from "./database.ts";
import { eventHistory } from "@tinker/start/server";
import { readExecution } from "../contracts/sync.ts";
import { raise } from "../errors.ts";
export const incrementCounter = operation({
  label: "incrementCounter",
  input: readExecution,
  depends: { database, history: eventHistory },
  run: async ({ database, history }, { input }) => {
    const [{ eq, sql }, { counter }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./sync.schema.ts"),
      import("@tinker/start/server"),
    ]);
    await database.transaction(async (tx) => {
      await history.lock(tx, "public");
      if (await history.find(tx, input.executionId, "public")) return;
      await tx.insert(execution).values({ id: input.executionId, stream: "public" });
      await tx.insert(counter).values({ id: 1 }).onConflictDoNothing();
      const row = (
        await tx
          .update(counter)
          .set({ value: sql`${counter.value} + 1` })
          .where(eq(counter.id, 1))
          .returning()
      ).at(0);
      if (!row) raise("StreamMissing", {});
      await history.append(tx, "public", input.executionId, [
        { kind: "change", change: { kind: "counter", value: row.value } },
        { kind: "result", result: { kind: "complete", action: "counter" } },
      ]);
    });
    return { executionId: input.executionId };
  },
});

import { operation } from "@tinker/core";
import { useData, useRun } from "@tinker/react";
import { counter } from "./state.ts";
import { syncClient } from "@tinker/start/client";
import { updateCounter } from "../transport/counter.functions.ts";
import { Button } from "./ui/button.tsx";
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from "./ui/card.tsx";
const increase = operation({
  label: "counter.increase",
  depends: { sync: syncClient },
  run: async ({ sync }, { random, signal }) => {
    const executionId = random.uuid();
    await sync.execute(executionId, { send: updateCounter, data: { executionId } }, signal);
  },
});
export function Counter() {
  const value = useData(counter);
  const action = useRun(increase);
  return (
    <Card>
      <CardHeader>
        <CardTitle>
          <h2>Shared counter</h2>
        </CardTitle>
        <CardDescription>Everyone can add one. No sign-in needed.</CardDescription>
      </CardHeader>
      <CardContent className="flex items-center justify-between gap-4">
        <output aria-label="Counter value" className="text-3xl font-semibold tabular-nums">
          {value}
        </output>
        <Button disabled={action.status === "pending"} onClick={() => action.run()}>
          {action.status === "pending" ? "Waiting for sync…" : "Increase counter"}
        </Button>
        {Boolean(action.error) && (
          <p role="alert" className="text-sm">
            The counter did not finish. Try again.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

import { createServerFn } from "@tanstack/react-start";
import { incrementCounter } from "../backend/index.ts";
import { readExecution } from "../contracts/sync.ts";
import { startRequests } from "@tinker/start";
import { readReceipt } from "./result.server.ts";
export const updateCounter = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readExecution)
  .handler(async ({ context, data }) =>
    readReceipt(
      await context.session.settle(incrementCounter, { input: data, signal: context.signal }),
    ),
  );
